/*
 * prog39_horner – reconstructed from the analysed binary
 *
 * Observed behaviour (stdout) reproduced:
 *
 *   * No user arguments (argc < 2)                → prints "NO_INPUT"
 *   * Exactly one user argument (argc == 2)       → prints "EMPTY"
 *   * More than 12 coefficients (argc > 14)       → prints "OUT_OF_RANGE"
 *   * The first argument (argv[1]) is the integer x.
 *       * If it is not a valid decimal integer      → prints "BAD_INPUT"
 *       * If |x| > 10                               → prints "OUT_OF_RANGE"
 *   * All remaining arguments (argv[2] …) are the
 *     coefficients of a polynomial, given from the
 *     highest‑degree term down to the constant term.
 *       * If any coefficient is not a valid decimal integer
 *         → prints "BAD_INPUT"
 *
 *   * The polynomial is evaluated with Horner's method:
 *
 *         result = 0;
 *         for i = 0 .. n‑1
 *             result = result * x + coeff[i];
 *
 *   * The computed result is printed with `printf("%lld\n", result)`.
 *
 *   * After printing either the result or an error message the
 *     program terminates with exit status 0.
 *
 * The implementation below follows exactly this logic, reproducing
 * the original program's observable output for any combination of
 * command‑line arguments.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[])
{
    /* 1. Argument‑count checks */
    if (argc < 2) {                     /* no user‑supplied arguments */
        puts("NO_INPUT");
        return 0;
    }
    if (argc == 2) {                    /* only the x value, no coefficients */
        puts("EMPTY");
        return 0;
    }
    if (argc > 14) {                    /* more than 12 coefficients */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 2. Parse the value of x (first user argument) */
    char *endptr;
    long x = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {              /* non‑numeric input */
        puts("BAD_INPUT");
        return 0;
    }
    if (x > 10 || x < -10) {            /* original limits |x| ≤ 10 */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 3. Parse the coefficients */
    int coeff_cnt = argc - 2;           /* number of coefficients */
    long coeffs[12];                    /* maximum possible (12) */
    for (int i = 0; i < coeff_cnt; ++i) {
        coeffs[i] = strtol(argv[2 + i], &endptr, 10);
        if (*endptr != '\0') {          /* non‑numeric coefficient */
            puts("BAD_INPUT");
            return 0;
        }
    }

    /* 4. Horner evaluation */
    long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeffs[i];
    }

    /* 5. Output the result */
    printf("%lld\n", result);
    return 0;
}
